55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	};
65	
66	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
67	
68	const policyBasePremium = (items: Item[]): number =>
69	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
70	
71	const quotePremium = (items: Item[]): number => {
72	  const policyBase = policyBasePremium(items);
73	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
74	};
75	
76	const runStep = (step: Step): StepResult => {
77	  if (step.op === "quote") {
78	    return { premium: quotePremium(step.items) };
79	  }
80	  throw new Error(`Unsupported step: ${step.op}`);
81	};
82	
83	export const runScenario = (scenario: Scenario): ScenarioResult => ({
84	  results: scenario.steps.map(runStep),
85	});
